<section class="panel mt"><h2>Edit rule #<?=e($editRule['id'])?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update_rule"><input type="hidden" name="scheme_id" value="<?=e($scheme['id'])?>"><input type="hidden" name="id" value="<?=e($editRule['id'])?>"><div class="field"><label>Group</label><select name="group_id" required><?php foreach($groups as $g): ?><option value="<?=e($g['id'])?>" <?=$editRule['group_id']==$g['id']?'selected':''?>><?=e($g['label'])?></option><?php endforeach; ?></select></div><div class="field"><label>Attribute</label><select name="attribute_key" required><?php foreach(['age','annual_income','state','occupation','education','gender','social_category','residence_type','disability_status','date_of_birth'] as $x): ?><option value="<?=e($x)?>" <?=$editRule['attribute_key']===$x?'selected':''?>><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach; ?></select></div><div class="field"><label>Operator</label><select name="operator" required><?php foreach(['eq','neq','gt','gte','lt','lte','in','not_in','true','false','exists','not_exists','before','after','range'] as $x): ?><option value="<?=e($x)?>" <?=$editRule['operator']===$x?'selected':''?>><?=e($x)?></option><?php endforeach; ?></select></div><div class="field"><label>Expected value</label><input name="expected_value" value="<?=e($editRule['expected_value'])?>"></div><div class="field full-field"><label>Description</label><input name="description" maxlength="300" required value="<?=e($editRule['description'])?>"></div><div class="field"><label>Applies when</label><select name="applicability_attribute"><option value="">Always applicable</option><?php foreach(['age','annual_income','state','occupation','education','gender','social_category','residence_type','disability_status','date_of_birth'] as $x): ?><option value="<?=e($x)?>" <?=$editRule['applicability_attribute']===$x?'selected':''?>><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach; ?></select></div><div class="field"><label>Applicability operator</label><select name="applicability_operator"><option value="">—</option><?php foreach(['eq','neq','gt','gte','lt','lte','in','not_in','true','false','exists','not_exists','before','after','range'] as $x): ?><option value="<?=e($x)?>" <?=$editRule['applicability_operator']===$x?'selected':''?>><?=e($x)?></option><?php endforeach; ?></select></div><div class="field"><label>Applicability value</label><input name="applicability_value" value="<?=e($editRule['applicability_value'])?>"></div><label class="check-row"><input type="checkbox" name="mandatory" value="1" <?=$editRule['mandatory']?'checked':''?>><span>Mandatory</span></label><label class="check-row"><input type="checkbox" name="active" value="1" <?=$editRule['active']?'checked':''?>><span>Active</span></label><div class="full-field form-actions"><button class="button" type="submit">Save rule</button><a class="button button-outline" href="<?=e(url('admin_scheme',['id'=>$scheme['id']]))?>">Cancel</a></div></form></section>
